// Type: PublicProof.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum PublicProof {
    Unkeyed,
    Keyed,
    Dispatched,
    Waiting,
    Passed,
    Failed,
}

// Record: PublicProof.
impl Record for PublicProof {
    type Limits = Limits;
    const TAIL: Path = paths::PUBLIC_PROOF_TAG;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 147)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 147)?.decoded)
    }

    fn write(&self, _limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        match self {
            Self::Unkeyed => field::put(out, &[0], paths::PUBLIC_PROOF_TAG),
            Self::Keyed => field::put(out, &[1], paths::PUBLIC_PROOF_TAG),
            Self::Dispatched => field::put(out, &[2], paths::PUBLIC_PROOF_TAG),
            Self::Waiting => field::put(out, &[3], paths::PUBLIC_PROOF_TAG),
            Self::Passed => field::put(out, &[4], paths::PUBLIC_PROOF_TAG),
            Self::Failed => field::put(out, &[5], paths::PUBLIC_PROOF_TAG),
        }
    }

    fn read(_limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let tag = reader.u8().ok_or(Problem { path: paths::PUBLIC_PROOF_TAG, reason: skein_codec::Reason::Short })?;
        match tag {
            0 => Ok(Self::Unkeyed),
            1 => Ok(Self::Keyed),
            2 => Ok(Self::Dispatched),
            3 => Ok(Self::Waiting),
            4 => Ok(Self::Passed),
            5 => Ok(Self::Failed),
            6..=u8::MAX => Err(Problem { path: paths::PUBLIC_PROOF_TAG, reason: skein_codec::Reason::Tag }),
        }
    }
}

