// Type: PublicLanding.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct PublicLanding {
    pub phase: PublicLandingPhase,
    pub hold: Option<PublicLandingHold>,
    pub preparation: u32,
    pub members: List<PublicMember>,
    pub stale_proofs: u32,
    pub holds_turn: bool,
    pub combined: Option<PublicCombined>,
    pub step: Option<PublicLandingStep>,
    pub search: Option<PublicSearch>,
}

// Record: PublicLanding.
impl Record for PublicLanding {
    type Limits = Limits;
    const TAIL: Path = paths::PUBLIC_LANDING_TAIL;

    fn encoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 173)?.encoded)
    }

    fn decoded_bound(limits: &Limits) -> Option<u64> {
        Some(skein_codec::bounds::declaration(TABLE, limits.values().as_slice(), CEILING_VALUES, 173)?.decoded)
    }

    #[cfg(debug_assertions)]
    fn decode(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        let value = Self::read(limits, reader)?;
        if !reader.is_empty() {
            return Err(Self::TAIL.problem(skein_codec::Reason::Trailing));
        }
        Ok(value)
    }

    fn write(&self, limits: &Limits, out: &mut skein_lib::Writer) -> Result<(), Problem> {
        field::put(out, &VERSION.to_be_bytes(), paths::PUBLIC_LANDING_VERSION)?;
        field::write(field::Nested, &self.phase, limits, out, paths::PUBLIC_LANDING_PHASE)?;
        field::write(field::Optional { item: field::Nested }, &self.hold, limits, out, paths::PUBLIC_LANDING_HOLD)?;
        field::write(field::U32, &self.preparation, limits, out, paths::PUBLIC_LANDING_PREPARATION)?;
        field::write(field::Sequence { limit: limits.public_landing_members.min(CEILINGS.public_landing_members), minimum: 12, item: field::Nested }, &self.members, limits, out, paths::PUBLIC_LANDING_MEMBERS)?;
        field::write(field::U32, &self.stale_proofs, limits, out, paths::PUBLIC_LANDING_STALE_PROOFS)?;
        field::write(field::Boolean, &self.holds_turn, limits, out, paths::PUBLIC_LANDING_HOLDS_TURN)?;
        field::write(field::Optional { item: field::Nested }, &self.combined, limits, out, paths::PUBLIC_LANDING_COMBINED)?;
        field::write(field::Optional { item: field::Nested }, &self.step, limits, out, paths::PUBLIC_LANDING_STEP)?;
        field::write(field::Optional { item: field::Nested }, &self.search, limits, out, paths::PUBLIC_LANDING_SEARCH)?;
        Ok(())
    }

    fn read(limits: &Limits, reader: &mut skein_lib::Reader<'_>) -> Result<Self, Problem> {
        field::version(reader, VERSION, paths::PUBLIC_LANDING_VERSION)?;
        Ok(Self {
            phase: field::read(field::Nested, limits, reader, paths::PUBLIC_LANDING_PHASE)?,
            hold: field::read(field::Optional { item: field::Nested }, limits, reader, paths::PUBLIC_LANDING_HOLD)?,
            preparation: field::read(field::U32, limits, reader, paths::PUBLIC_LANDING_PREPARATION)?,
            members: field::read(field::Sequence { limit: limits.public_landing_members.min(CEILINGS.public_landing_members), minimum: 12, item: field::Nested }, limits, reader, paths::PUBLIC_LANDING_MEMBERS)?,
            stale_proofs: field::read(field::U32, limits, reader, paths::PUBLIC_LANDING_STALE_PROOFS)?,
            holds_turn: field::read(field::Boolean, limits, reader, paths::PUBLIC_LANDING_HOLDS_TURN)?,
            combined: field::read(field::Optional { item: field::Nested }, limits, reader, paths::PUBLIC_LANDING_COMBINED)?,
            step: field::read(field::Optional { item: field::Nested }, limits, reader, paths::PUBLIC_LANDING_STEP)?,
            search: field::read(field::Optional { item: field::Nested }, limits, reader, paths::PUBLIC_LANDING_SEARCH)?,
        })
    }
}

